-- Tabela oficial de CFOP (Convênio s/nº de 15/12/1970, Anexo II) na versão do
-- Portal Nacional da NF-e: Informe Técnico 2023.002 v2.10, "Tabela de CFOP",
-- publicada em 04/09/2026 (619 códigos, com título, nota explicativa,
-- vigência e os indicadores que a SEFAZ usa nas validações).
--
-- Nenhuma migration carregava a tabela: cada base tinha só o que alguém
-- cadastrou à mão (a Usimac, nenhum código; a VFIS0300 aparecia vazia).
-- Os campos da empresa (utilização, indicador de operação, DIFAL, doação,
-- anexo do Simples) e a descrição já digitada são preservados.

ALTER TABLE cfops
    ALTER COLUMN description TYPE VARCHAR(400),
    ADD COLUMN oficial          BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN inicio_vigencia  DATE,
    ADD COLUMN fim_vigencia     DATE,
    ADD COLUMN ind_nfe          BOOLEAN NOT NULL DEFAULT TRUE,
    ADD COLUMN ind_comunica     BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN ind_transp       BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN ind_devol        BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN ind_retor        BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN ind_anula        BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN ind_remes        BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN ind_comb         BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN ind_exc_ibscbs   BOOLEAN NOT NULL DEFAULT FALSE;

INSERT INTO cfops (code, description, description_full, inicio_vigencia, fim_vigencia,
    ind_nfe, ind_comunica, ind_transp, ind_devol, ind_retor, ind_anula, ind_remes, ind_comb, ind_exc_ibscbs, oficial)
SELECT v.code, v.titulo, v.nota, v.ini, v.fim,
    v.nfe, v.comunica, v.transp, v.devol, v.retor, v.anula, v.remes, v.comb, v.exc, TRUE
  FROM (VALUES
    (1101,'Compra para industrialização ou produção rural.','Classificam-se neste código as compras de mercadorias para serem utilizadas em processo de industrialização ou produção rural.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1102,'Compra para comercialização.','Classificam-se neste código as compras de mercadorias para serem comercializadas.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1111,'Compra para industrialização de mercadoria recebida anteriormente em consignação industrial.','Classificam-se neste código as compras efetivas de mercadorias para serem utilizadas em processo de industrialização, recebidas anteriormente a título de consignação industrial.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1113,'Compra para comercialização, de mercadoria recebida anteriormente em consignação mercantil.','Classificam-se neste código as compras efetivas de mercadorias recebidas anteriormente a título de consignação mercantil.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1116,'Compra para industrialização ou produção rural originada de encomenda para recebimento futuro.','Classificam-se neste código as compras de mercadorias para serem utilizadas em processo de industrialização ou produção rural, quando da entrada real da mercadoria, cuja aquisição tenha sido classificada no código “1.922 - Lançamento efetuado a título de simples faturamento decorrente de compra para recebimento futuro”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1117,'Compra para comercialização originada de encomenda para recebimento futuro.','Classificam-se neste código as compras de mercadorias para serem comercializadas, quando da entrada real da mercadoria, cuja aquisição tenha sido classificada no código “1.922 - Lançamento efetuado a título de simples faturamento decorrente de compra para recebimento futuro”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1118,'Compra de mercadoria para comercialização pelo adquirente originário, entregue pelo vendedor remetente ao destinatário, em venda à ordem.','Classificam-se neste código as compras de mercadorias já comercializadas, que, sem transitar pelo estabelecimento do adquirente originário, sejam entregues pelo vendedor remetente diretamente ao destinatário, em operação de venda à ordem, cuja venda tenha sido classificada, pelo adquirente originário, no código “5.120 - Venda de mercadoria adquirida ou recebida de terceiros entregue ao destinatário pelo vendedor remetente, em venda à ordem”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1120,'Compra para industrialização ou produção rural, em venda à ordem, já recebida do vendedor remetente.','Classificam-se neste código as compras de mercadorias para serem utilizadas em processo de industrialização ou produção rural, em vendas à ordem, já recebidas do vendedor remetente, por ordem do adquirente originário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1121,'Compra para comercialização, em venda à ordem, já recebida do vendedor remetente.','Classificam-se neste código as compras de mercadorias para serem comercializadas, em vendas à ordem, já recebidas do vendedor remetente por ordem do adquirente originário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1122,'Compra para industrialização em que a mercadoria foi remetida pelo fornecedor ao industrializador sem transitar pelo estabelecimento adquirente.','Classificam-se neste código as compras de mercadorias para serem utilizadas em processo de industrialização, remetidas pelo fornecedor para o industrializador sem que a mercadoria tenha transitado pelo estabelecimento do adquirente.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1124,'Industrialização efetuada por outra empresa.','Classificam-se neste código as entradas de mercadorias industrializadas por terceiros, compreendendo os valores referentes aos serviços prestados e os das mercadorias de propriedade do industrializador empregadas no processo industrial. Quando a industrialização efetuada se referir a bens do ativo imobilizado ou de mercadorias para uso ou consumo do estabelecimento encomendante, a entrada deverá ser classificada nos códigos “1.551 - Compra de bem para o ativo imobilizado” ou “1.556 - Compra de material para uso ou consumo”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1125,'Industrialização efetuada por outra empresa quando a mercadoria remetida para utilização no processo de industrialização não transitou pelo estabelecimento adquirente da mercadoria.','Classificam-se neste código as entradas de mercadorias industrializadas por outras empresas, em que as mercadorias remetidas para utilização no processo de industrialização não transitaram pelo estabelecimento do adquirente das mercadorias, compreendendo os valores referentes aos serviços prestados e os das mercadorias de propriedade do industrializador empregadas no processo industrial. Quando a industrialização efetuada se referir a bens do ativo imobilizado ou de mercadorias para uso ou consumo do estabelecimento encomendante, a entrada deverá ser classificada nos códigos “1.551 - Compra de bem para o ativo imobilizado” ou “1.556 - Compra de material para uso ou consumo”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1126,'Compra para utilização na prestação de serviço sujeita ao ICMS.','Classificam-se neste código as entradas de mercadorias para serem utilizadas nas prestações de serviços sujeitas ao ICMS.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1128,'Compra para utilização na prestação de serviço sujeita ao ISSQN.','Classificam-se neste código as entradas de mercadorias para serem utilizadas nas prestações de serviços sujeitas ao ISSQN.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1131,'Entrada de mercadoria, com previsão de posterior ajuste ou fixação de preço, em ato cooperativo.','Classificam-se neste código as entradas de mercadorias, com previsão de posterior ajuste ou fixação de preço, proveniente de cooperado, bem como proveniente de outra cooperativa, em que a saída tenha sido classificada no código “5.131 - Remessa de produção do estabelecimento, com previsão de posterior ajuste ou fixação de preço, em ato cooperativo”.','2018-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1132,'Fixação de preço de produção do estabelecimento produtor, inclusive quando remetidas anteriormente com previsão de posterior ajuste ou fixação de preço, em ato cooperativo, para comercialização.','Classificam-se neste código as entradas para comercialização referentes à fixação de preço de produção do estabelecimento do produtor, inclusive quando remetidas anteriormente com previsão de posterior ajuste ou fixação de preço, em ato cooperativo, cuja saída tenha sido classificada no código “5.132 - Fixação de preço de produção do estabelecimento, inclusive quando remetidas anteriormente com previsão de posterior ajuste ou fixação de preço, em ato cooperativo”.','2018-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1135,'Fixação de preço de produção do estabelecimento produtor, inclusive quando remetidas anteriormente com previsão de posterior ajuste ou fixação de preço, em ato cooperativo, para industrialização.','Classificam-se neste código as entradas para industrialização referentes à fixação de preço de produção do estabelecimento do produtor, inclusive quando remetidas anteriormente com previsão de posterior ajuste ou fixação de preço, em ato cooperativo, cuja saída tenha sido classificada no código “5.132 - Fixação de preço de produção do estabelecimento, inclusive quando remetidas anteriormente com previsão de posterior ajuste ou fixação de preço, em ato cooperativo”.','2018-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1151,'Transferência para industrialização ou produção rural.','Classificam-se neste código as entradas de mercadorias recebidas em transferência de outro estabelecimento da mesma empresa, para serem utilizadas em processo de industrialização ou produção rural.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1152,'Transferência para comercialização.','Classificam-se neste código as entradas de mercadorias recebidas em transferência de outro estabelecimento da mesma empresa, para serem comercializadas.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1153,'Transferência de energia elétrica para distribuição.','Classificam-se neste código as entradas de energia elétrica recebida em transferência de outro estabelecimento da mesma empresa, para distribuição.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1154,'Transferência para utilização na prestação de serviço.','Classificam-se neste código as entradas de mercadorias recebidas em transferência de outro estabelecimento da mesma empresa, para serem utilizadas nas prestações de serviços.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1159,'Entrada decorrente do fornecimento de produto ou mercadoria em ato cooperativo.','Classificam-se neste código as entradas decorrentes de fornecimento de produtos ou mercadorias por estabelecimento de cooperativa destinados a seus cooperados ou a estabelecimento de outra cooperativa, cujo fornecimento tenha sido classificado nos códigos “5.159 - Fornecimento de produção do estabelecimento em ato cooperativo” ou “5.160 - Fornecimento de mercadoria adquirida ou recebida de terceiros em ato cooperativo”.','2018-09-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1201,'Devolução de venda de produção do estabelecimento.','Classificam-se neste código as devoluções de vendas de produtos industrializados ou produzidos pelo próprio estabelecimento, cujas saídas tenham sido classificadas nos códigos “5.101 - Venda de produção do estabelecimento”,“ 5.103 - Venda de produção do estabelecimento, efetuada fora do estabelecimento” ou “5.105 - Venda de produção do estabelecimento que não deva por ele transitar”. Também se classificam neste código os retornos de mercadorias não entregues ao destinatário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1202,'Devolução de venda de mercadoria adquirida ou recebida de terceiros, ou qualquer devolução de mercadoria efetuada pelo MEI com exceção das classificadas nos códigos 1.503, 1.504, 1.505 e 1.506.','Classificam-se neste código as devoluções de vendas de mercadorias adquiridas ou recebidas de terceiros, que não tenham sido objeto de industrialização no estabelecimento, cujas saídas tenham sido classificadas nos códigos “5.102 - Venda de mercadoria adquirida ou recebida de terceiros, ou qualquer venda de mercadoria efetuada pelo MEI com exceção das saídas classificadas nos códigos 5.501, 5.502, 5.504 e 5.505”, “5.104 - Venda de mercadoria adquirida ou recebida de terceiros, efetuada fora do estabelecimento” ou “5.106 - Venda de mercadoria adquirida ou recebida de terceiros, que não deva por ele transitar”. Também se classificam neste código quaisquer devoluções de mercadorias efetuadas pelo MEI com exceção das classificadas nos códigos “1.503 - Entrada decorrente de devolução de produto remetido com fim específico de exportação, de produção do estabelecimento”, “1.504 - Entrada decorrente de devolução, inclusive simbólica, de mercadoria remetida com fim específico de exportação, adquirida ou recebida de terceiros”, “1.505 - Entrada decorrente de devolução, inclusive simbólica, de mercadorias remetidas para formação de lote de exportação, de produtos industrializados ou produzidos pelo próprio estabelecimento" ou "1.506 - Entrada decorrente de devolução, inclusive simbólica, de mercadorias adquiridas ou recebidas de terceiros, remetidas para formação de lote de exportação”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1203,'Devolução de venda de produção do estabelecimento, destinada à Zona Franca de Manaus ou Áreas de Livre Comércio.','Classificam-se neste código as devoluções de vendas de produtos industrializados ou produzidos pelo próprio estabelecimento, cujas saídas tenham sido classificadas no código “5.109 - Venda de produção do estabelecimento, destinada à Zona Franca de Manaus ou Áreas de Livre Comércio”. Também se classificam neste código os retornos de mercadorias não entregues ao destinatário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1204,'Devolução de venda de mercadoria adquirida ou recebida de terceiros, destinada à Zona Franca de Manaus ou Áreas de Livre Comércio.','Classificam-se neste código as devoluções de vendas de mercadorias adquiridas ou recebidas de terceiros, cujas saídas tenham sido classificadas no código “5.110 - Venda de mercadoria adquirida ou recebida de terceiros, destinada à Zona Franca de Manaus ou Áreas de Livre Comércio”. Também se classificam neste código os retornos de mercadorias não entregues ao destinatário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1205,'Anulação de valor relativo à prestação de serviço de comunicação.','Classificam-se neste código as anulações correspondentes a valores faturados indevidamente, decorrentes de prestações de serviços de comunicação.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE),
    (1206,'Anulação de valor relativo à prestação de serviço de transporte.','Classificam-se neste código as anulações correspondentes a valores faturados indevidamente, decorrentes de prestações de serviços de transporte.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE),
    (1207,'Anulação de valor relativo à venda de energia elétrica.','Classificam-se neste código as anulações correspondentes a valores faturados indevidamente, decorrentes de venda de energia elétrica.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE),
    (1208,'Devolução de produção do estabelecimento, remetida em transferência.','Classificam-se neste código as devoluções de produtos industrializados ou produzidos pelo próprio estabelecimento, transferidos para outros estabelecimentos da mesma empresa. Também se classificam neste código os retornos de mercadorias não entregues ao destinatário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1209,'Devolução de mercadoria adquirida ou recebida de terceiros, remetida em transferência.','Classificam-se neste código as devoluções de mercadorias adquiridas ou recebidas de terceiros, transferidas para outros estabelecimentos da mesma empresa. Também se classificam neste código os retornos de mercadorias não entregues ao destinatário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1212,'Devolução de venda no mercado interno de mercadoria industrializada e insumo importado sob o Regime Aduaneiro Especial de Entreposto Industrial sob Controle Informatizado do Sistema Público de Escrituração Digital (Recof-Sped).','Classificam-se neste código as devoluções de vendas de mercadorias industrializadas e insumos importados pelo estabelecimento, cujas saídas tenham sido classificadas no código “5.129 - Venda de mercadoria industrializada e de insumo importado sob o amparo do Regime Aduaneiro Especial de Entreposto Industrial sob Controle Informatizado do Sistema Público de Escrituração Digital (Recof-Sped)”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1213,'Devolução de remessa de produção do estabelecimento, com previsão de posterior ajuste ou fixação de preço, em ato cooperativo.','Classificam-se neste código as devoluções de remessa que tenham sido classificadas no código “5.131 - Remessa de produção do estabelecimento, com previsão de posterior ajuste ou fixação de preço, em ato cooperativo”.','2018-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1214,'Devolução referente à fixação de preço de produção do estabelecimento produtor em ato cooperativo.','Classificam-se neste código as devoluções referentes à fixação de preço de produção do estabelecimento produtor cuja saída tenha sido classificada no código “5.132 - Fixação de preço de produção do estabelecimento, inclusive quando remetidas anteriormente com previsão de posterior ajuste ou fixação de preço, em ato cooperativo”.','2018-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1215,'Devolução de fornecimento de produção do estabelecimento em ato cooperativo.','Classificam-se neste código as devoluções de fornecimentos de produtos industrializados ou produzidos pelo próprio estabelecimento de cooperativa destinados a seus cooperados ou a estabelecimento de outra cooperativa, cujas saídas tenham sido classificadas no código “5.159 - Fornecimento de produção do estabelecimento em ato cooperativo”.','2019-05-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1216,'Devolução de fornecimento de mercadoria adquirida ou recebida de terceiros em ato cooperativo.','Classificam-se neste código as devoluções de fornecimentos de mercadorias adquiridas ou recebidas de terceiros, que não tenham sido objeto de qualquer processo industrial no estabelecimento de cooperativa, destinados a seus cooperados ou a estabelecimento de outra cooperativa, cujas saídas tenham sido classificadas no código “5.160 - Fornecimento de mercadoria adquirida ou recebida de terceiros em ato cooperativo”.','2019-05-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1251,'Compra de energia elétrica para distribuição ou comercialização.','Classificam-se neste código as compras de energia elétrica utilizada em sistema de distribuição ou comercialização. Também se classificam neste código as compras de energia elétrica por cooperativas para distribuição aos seus cooperados.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1252,'Compra de energia elétrica por estabelecimento industrial.','Classificam-se neste código as compras de energia elétrica utilizada no processo de industrialização. Também se classificam neste código as compras de energia elétrica utilizada por estabelecimento industrial de cooperativa.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1253,'Compra de energia elétrica por estabelecimento comercial.','Classificam-se neste código as compras de energia elétrica utilizada por estabelecimento comercial. Também se classificam neste código as compras de energia elétrica utilizada por estabelecimento comercial de cooperativa.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1254,'Compra de energia elétrica por estabelecimento prestador de serviço de transporte.','Classificam-se neste código as compras de energia elétrica utilizada por estabelecimento prestador de serviços de transporte.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1255,'Compra de energia elétrica por estabelecimento prestador de serviço de comunicação.','Classificam-se neste código as compras de energia elétrica utilizada por estabelecimento prestador de serviços de comunicação.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1256,'Compra de energia elétrica por estabelecimento de produtor rural.','Classificam-se neste código as compras de energia elétrica utilizada por estabelecimento de produtor rural.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1257,'Compra de energia elétrica para consumo por demanda contratada.','Classificam-se neste código as compras de energia elétrica para consumo por demanda contratada, que prevalecerá sobre os demais códigos deste grupo.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1301,'Aquisição de serviço de comunicação para execução de serviço da mesma natureza.','Classificam-se neste código as aquisições de serviços de comunicação utilizados nas prestações de serviços da mesma natureza.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1302,'Aquisição de serviço de comunicação por estabelecimento industrial.','Classificam-se neste código as aquisições de serviços de comunicação utilizados por estabelecimento industrial. Também se classificam neste código as aquisições de serviços de comunicação utilizados por estabelecimento industrial de cooperativa.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1303,'Aquisição de serviço de comunicação por estabelecimento comercial.','Classificam-se neste código as aquisições de serviços de comunicação utilizados por estabelecimento comercial. Também se classificam neste código as aquisições de serviços de comunicação utilizados por estabelecimento comercial de cooperativa.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1304,'Aquisição de serviço de comunicação por estabelecimento de prestador de serviço de transporte.','Classificam-se neste código as aquisições de serviços de comunicação utilizados por estabelecimento prestador de serviço de transporte.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1305,'Aquisição de serviço de comunicação por estabelecimento de geradora ou de distribuidora de energia elétrica.','Classificam-se neste código as aquisições de serviços de comunicação utilizados por estabelecimento de geradora ou de distribuidora de energia elétrica.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
