    (1455,'Retorno de insumo não utilizado na produção - Sistema de Integração e Parceria Rural.','Classificam-se neste código as entradas referentes ao retorno de insumos não utilizados pelo produtor na criação, recriação ou engorda de animais pelo sistema integrado e de produção animal, inclusive em sistema de confinamento, cujas saídas tenham sido classificadas no código “5.455 - Retorno de insumos não utilizados na produção - Sistema de Integração e Parceria Rural”, inclusive as operações entre cooperativa singular e cooperativa central.','2019-12-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE),
    (1456,'Entrada referente à remuneração do produtor no Sistema de Integração e Parceria Rural.','Classificam-se neste código as entradas da parcela da produção do produtor realizadas em sistema de integração e produção animal, quando da entrega ao integrador ou parceiro. Também se classificam neste código as entradas, em ato cooperativo, inclusive as operações entre cooperativa singular e cooperativa central.','2019-12-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1501,'Entrada de mercadoria recebida com fim específico de exportação.','Classificam-se neste código as entradas de mercadorias em estabelecimento de “trading company”, empresa comercial exportadora ou outro estabelecimento do remetente, com fim específico de exportação.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (1503,'Entrada decorrente de devolução de produto remetido com fim específico de exportação, de produção do estabelecimento.','Classificam-se neste código as devoluções de produtos industrializados ou produzidos pelo próprio estabelecimento, remetidos a “trading company”, a empresa comercial exportadora ou a outro estabelecimento do remetente, com fim específico de exportação, cujas saídas tenham sido classificadas no código “5.501 - Remessa de produção do estabelecimento, com fim específico de exportação”. Também se classificam neste código os retornos de mercadorias não entregues ao destinatário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
