    (2455,'Retorno de insumo não utilizado na produção - Sistema de Integração e Parceria Rural.','Classificam-se neste código as entradas referentes aos retornos de insumos não utilizados pelo produtor na criação, recriação ou engorda de animais pelo sistema integrado e de produção animal, cujas saídas tenham sido classificadas no código “6.455 - Retorno de insumos não utilizados na produção - Sistema de Integração e Parceria Rural”, inclusive as operações entre cooperativa singular e cooperativa central.','2019-12-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE),
