    (2501,'Entrada de mercadoria recebida com fim específico de exportação.','Classificam-se neste código as entradas de mercadorias em estabelecimento de “trading company”, empresa comercial exportadora ou outro estabelecimento do remetente, com fim específico de exportação.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (2503,'Entrada decorrente de devolução de produto remetido com fim específico de exportação, de produção do estabelecimento.','Classificam-se neste código as devoluções de produtos industrializados ou produzidos pelo próprio estabelecimento, remetidos a “trading company”, a empresa comercial exportadora ou a outro estabelecimento do remetente, com fim específico de exportação, cujas saídas tenham sido classificadas no código “6.501 - Remessa de produção do estabelecimento, com fim específico de exportação”. Também se classificam neste código os retornos de mercadorias não entregues ao destinatário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (2504,'Entrada decorrente de devolução, inclusive simbólica, de mercadoria remetida com fim específico de exportação, adquirida ou recebida de terceiros.','Classificam-se neste código as devoluções físicas ou simbólicas de mercadorias adquiridas ou recebidas de terceiros remetidas a “trading company”, a empresa comercial exportadora ou a outro estabelecimento do remetente, com fim específico de exportação, cujas saídas tenham sido classificadas no código “6.502 - Remessa de mercadoria adquirida ou recebida de terceiros, com fim específico de exportação”. Também se classificam neste código os retornos de mercadorias não entregues ao destinatário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (2505,'Entrada decorrente de devolução, inclusive simbólica, de mercadorias remetidas para formação de lote de exportação, de produtos industrializados ou produzidos pelo próprio estabelecimento.','Classificam-se neste código as devoluções físicas ou simbólicas de mercadorias, bem como o retorno de mercadorias não entregues, remetidas para formação de lote de exportação, cujas saídas tenham sido classificadas no código “6.504 - Remessa de mercadorias para formação de lote de exportação, de produtos industrializados ou produzidos pelo próprio estabelecimento”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (2506,'Entrada decorrente de devolução, inclusive simbólica, de mercadorias adquiridas ou recebidas de terceiros, remetidas para formação de lote de exportação.','Classificam-se neste código as devoluções físicas ou simbólicas de mercadorias remetidas para formação de lote de exportação em armazéns alfandegados, entrepostos aduaneiros ou outros estabelecimentos que venham a ser regulamentados pela legislação tributária de cada unidade da Federação, efetuadas pelo estabelecimento depositário, cujas saídas tenham sido classificadas no código “6.505 - Remessa de mercadorias, adquiridas ou recebidas de terceiros, para formação de lote de exportação”. Também se classificam neste código os retornos de mercadorias não entregues ao destinatário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
