    (3201,'Devolução de venda de produção do estabelecimento.','Classificam-se neste código as devoluções de vendas de produtos industrializados ou produzidos pelo próprio estabelecimento, cujas saídas tenham sido classificadas no código “7.101 - Venda de produção do estabelecimento” ou “7.105 - Venda de produção do estabelecimento armazenada em depósito fechado, armazém geral ou outro estabelecimento da mesma empresa ou de terceiro, que não deva por ele transitar”. Também se classificam neste código os retornos de mercadorias não entregues ao destinatário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
