    (6118,'Venda de produção do estabelecimento industrial ou rural, entregue ao destinatário por conta e ordem do adquirente originário, em venda à ordem.','Classificam-se neste código as vendas à ordem de produtos, industrializados ou oriundos de produção rural pelo estabelecimento, entregues ao destinatário por conta e ordem do adquirente originário.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
