    (6659,'Transferência de combustíveis ou lubrificantes adquiridos ou recebidos de terceiros.','Classificam-se neste código as transferências de combustíveis ou lubrificantes, adquiridos ou recebidos de terceiros, para outro estabelecimento da mesma empresa.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (6660,'Devolução de compra de combustíveis ou lubrificantes adquiridos para industrialização subsequente.','Classificam-se neste código as devoluções de compras de combustíveis ou lubrificantes adquiridos para industrialização do próprio produto, cujas entradas tenham sido classificadas no código “2.651 - Compra de combustíveis ou lubrificantes para industrialização subsequente”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (6661,'Devolução de compra de combustíveis ou lubrificantes adquiridos para comercialização.','Classificam-se neste código as devoluções de compras de combustíveis ou lubrificantes adquiridos para comercialização, cujas entradas tenham sido classificadas no código “2.652 - Compra de combustíveis ou lubrificantes para comercialização”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
    (6662,'Devolução de compra de combustíveis ou lubrificantes adquiridos por consumidor ou usuário final.','Classificam-se neste código as devoluções de compras de combustíveis ou lubrificantes adquiridos para consumo em processo de industrialização de outros produtos, na prestação de serviços ou por usuário final, cujas entradas tenham sido classificadas no código “2.653 - Compra de combustíveis ou lubrificantes por consumidor ou usuário final”.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
