    (6665,'Retorno simbólico de combustíveis ou lubrificantes recebidos para armazenagem.','Classificam-se neste código os retornos simbólicos de combustíveis ou lubrificantes recebidos para armazenagem, quando as mercadorias armazenadas tenham sido objeto de saída a qualquer título e não devam retornar ao estabelecimento depositante.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,TRUE,FALSE,FALSE,TRUE,FALSE),
