    (6916,'Retorno de mercadoria ou bem recebido para conserto ou reparo.','Classificam-se neste código as remessas em devolução de mercadorias ou bens recebidos para conserto ou reparo.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,TRUE),
    (6917,'Remessa de mercadoria em consignação mercantil ou industrial.','Classificam-se neste código as remessas de mercadorias a título de consignação mercantil ou industrial.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,TRUE,FALSE,FALSE),
    (6918,'Devolução de mercadoria recebida em consignação mercantil ou industrial.','Classificam-se neste código as devoluções de mercadorias recebidas anteriormente a título de consignação mercantil ou industrial.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE),
