    (7949,'Outra saída de mercadoria ou prestação de serviço não especificada.','Classificam-se neste código as outras saídas de mercadorias ou prestações de serviços que não tenham sido especificadas neste grupo.','2006-01-01'::date,NULL::date,TRUE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE)
  ) AS v(code, titulo, nota, ini, fim, nfe, comunica, transp, devol, retor, anula, remes, comb, exc)
ON CONFLICT (code) DO UPDATE SET
    description      = CASE WHEN btrim(cfops.description) = '' THEN EXCLUDED.description ELSE cfops.description END,
    description_full = COALESCE(NULLIF(btrim(cfops.description_full), ''), EXCLUDED.description_full),
    inicio_vigencia  = EXCLUDED.inicio_vigencia,
    fim_vigencia     = EXCLUDED.fim_vigencia,
    ind_nfe          = EXCLUDED.ind_nfe,
    ind_comunica     = EXCLUDED.ind_comunica,
    ind_transp       = EXCLUDED.ind_transp,
    ind_devol        = EXCLUDED.ind_devol,
    ind_retor        = EXCLUDED.ind_retor,
    ind_anula        = EXCLUDED.ind_anula,
    ind_remes        = EXCLUDED.ind_remes,
    ind_comb         = EXCLUDED.ind_comb,
    ind_exc_ibscbs   = EXCLUDED.ind_exc_ibscbs,
    oficial          = TRUE;

SELECT instalar_conferencia_de_empresa();
